const escapeHtml = (value = '') =>
    value
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#39;');

const normalizeAccountEmail = (value = '') => value.trim().toLowerCase();

const getLegacyDraftStorageKey = (email = 'guest-session') => `sa-cv-private-draft-v4-${email}`;
const getSecureUserDraftCacheKey = (userId = 'guest') => `sa-cv-secure-draft-v1-${userId}`;
const CV_GUEST_DRAFT_CACHE_KEY = 'sa-cv-guest-draft-v1';

const getLegacyAuthKeys = () => ['sa-cv-private-accounts-v1', 'sa-cv-private-session-v1', getLegacyDraftStorageKey()];

const isOfficialCvPersistenceHost = () => {
    const hostname = window.location.hostname.replace(/^www\./i, '').toLowerCase();
    return window.location.protocol === 'https:' && hostname === 'sacreationweb.com';
};

const getCvDraftTimestamp = (payload, fallback = '') => {
    const value = [payload?.savedAt, payload?.updated_at, fallback]
        .find((candidate) => Number.isFinite(Date.parse(candidate || '')));
    return value ? Date.parse(value) : 0;
};

const pickNewestCvDraftPayload = (drafts = []) =>
    drafts
        .filter((draft) => draft?.payload)
        .sort((left, right) => getCvDraftTimestamp(right.payload, right.updatedAt) - getCvDraftTimestamp(left.payload, left.updatedAt))[0]?.payload || null;

const getComparableCvDraftPayload = (payload = {}) => {
    const source = payload && typeof payload === 'object' ? payload : {};
    return {
        values: source.values && typeof source.values === 'object' ? source.values : {},
        editableContent: source.editableContent && typeof source.editableContent === 'object' ? source.editableContent : {},
        sectionTitleStyles: source.sectionTitleStyles && typeof source.sectionTitleStyles === 'object' ? source.sectionTitleStyles : {},
        sectionOrder: Array.isArray(source.sectionOrder) ? source.sectionOrder : [],
        contentLocale: source.contentLocale === 'en' ? 'en' : 'fr',
        preserveEmptyLanguages: source.preserveEmptyLanguages === true,
        profilePhoto: source.profilePhoto && typeof source.profilePhoto === 'object' ? source.profilePhoto : null,
    };
};

const getStableComparableValue = (value) => {
    if (Array.isArray(value)) {
        return value.map(getStableComparableValue);
    }

    if (!value || typeof value !== 'object') {
        return value ?? null;
    }

    return Object.keys(value)
        .sort()
        .reduce((output, key) => {
            const nextValue = value[key];
            if (typeof nextValue !== 'undefined') {
                output[key] = getStableComparableValue(nextValue);
            }
            return output;
        }, {});
};

const areCvDraftPayloadsEquivalent = (left = {}, right = {}) =>
    JSON.stringify(getStableComparableValue(getComparableCvDraftPayload(left))) ===
    JSON.stringify(getStableComparableValue(getComparableCvDraftPayload(right)));

const dedupeExactTrimmedItems = (items = []) => {
    const seen = new Set();
    const output = [];

    items.forEach((item) => {
        const value = String(item || '').trim();
        if (!value || seen.has(value)) {
            return;
        }
        seen.add(value);
        output.push(value);
    });

    return output;
};

