templatePresetChips.forEach((chip) => {
    chip.addEventListener('click', () => {
        if (!cvForm) {
            return;
        }

        if (retiredTemplatePresets.has(chip.dataset.templatePreset || '')) {
            const fallbackPreset = templatePresets[fallbackTemplatePreset];
            if (!fallbackPreset) {
                return;
            }

            Object.entries(fallbackPreset).forEach(([key, value]) => {
                const field = cvForm.elements[key];
                if (field) {
                    field.value = value;
                }
            });
            updateCvPreview();
            resetCvHistory();
            saveCvDraft(true);
            setCvStatus('Modele remplace par Premium');
            return;
        }

        const preset = templatePresets[chip.dataset.templatePreset || ''];
        if (!preset) {
            return;
        }

        // A model card is the same explicit user choice as the advanced
        // selector. Mark it before the silent save so ATS is not mistaken for
        // an automatic fallback and replaced by the previously saved model.
        lastUserLayoutThemeChangeAt = Date.now();

        Object.entries(preset).forEach(([key, value]) => {
            const field = cvForm.elements[key];
            if (field) {
                field.value = value;
            }
        });

        updateCvPreview();
        templatePresetChips.forEach((button) => {
            const isActive = button === chip;
            button.classList.toggle('is-active', isActive);
            button.setAttribute('aria-pressed', String(isActive));
        });
        resetCvHistory();
        saveCvDraft(true);
        setCvStatus('Nouveau modele applique');
    });
});

